use serde_json::{json,Value};use std::{fs,path::Path};
const R:&str="/home/ubuntu/src/zopro-perf-work/balanced-kh-qualification175";
fn main(){let r=Path::new(R);let a:Value=serde_json::from_slice(&fs::read(r.join("analysis.json")).unwrap()).unwrap();let ids:Value=serde_json::from_slice(&fs::read(r.join("identities.json")).unwrap()).unwrap();assert_eq!(ids["accepted"]["sha256"],ids["OFF"]["sha256"]);assert_eq!(a["failed_checks"],json!(["1x2-w16/OFF/accepted"]));
 let mut rows=Vec::new();let mut x=Vec::new();let mut y=Vec::new();
 for b in 0..15{let mut variants=serde_json::Map::new();for v in ["accepted","OFF","ON"]{let row=&a["cells"][format!("1x2-w16/{v}")]["blocks"][b];assert_eq!(row["block"],b);let s=&row["summary"];let rounds=s["rounds"].as_f64().unwrap();let wall=s["loop_wall_ms"].as_f64().unwrap();let cpu=s["user_cpu_ms"].as_f64().unwrap()+s["system_cpu_ms"].as_f64().unwrap();let invol=s["involuntary_switches"].as_f64().unwrap();variants.insert(v.into(),json!({"median_ms":row["median_ms"],"CPU_ms_per_request":cpu/rounds,"mean_loop_ms_per_request":wall/rounds,"average_CPU_cores_during_loop":cpu/wall,"involuntary_switches":s["involuntary_switches"],"voluntary_switches":s["voluntary_switches"],"minor_faults":s["minor_faults"],"RSS_MiB":row["RSS_MiB"]}));if v!="ON"{x.push(invol/rounds);y.push(wall/rounds);}}
 rows.push(json!({"block":b,"OFF_over_accepted":a["pairs"]["1x2-w16/OFF/accepted"]["ratios"][b],"variants":variants}));}
 let n=x.len()as f64;let mx=x.iter().sum::<f64>()/n;let my=y.iter().sum::<f64>()/n;let cov=x.iter().zip(&y).map(|(x,y)|(x-mx)*(y-my)).sum::<f64>();let vx=x.iter().map(|x|(x-mx).powi(2)).sum::<f64>();let vy=y.iter().map(|y|(y-my).powi(2)).sum::<f64>();
 let result=json!({"scope":"offline exploration of all existing15blocks;no new captures or exclusions;no changed gate","same_baseline_binary_sha256":ids["accepted"]["sha256"],"driver_usage_scope":"getrusage SELF after three primes;CPU/switch deltas cover measured loop;loopwall includes loop bookkeeping but samples are emitted afterward","baseline16_processes":30,"Pearson_context_switches_vs_mean_wall_descriptive":cov/(vx*vy).sqrt(),"causality_established":false,"runqueue_wait_or_external_interference_not_directly_measured":true,"full_gate_stays_failed":true,"candidate_checks_all_passed":true,"rows":rows});fs::write(r.join("calibration-audit.json"),serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("Offline30baselineprocess correlation{};all15blocksretained;gateunchanged",result["Pearson_context_switches_vs_mean_wall_descriptive"]);
}
